#!/usr/bin/env node
/**
 * normalize-seeddata.js
 * Read seedData/{jobs,companies,profiles}.json (generated by extract-from-pages.js)
 * Normalize fields to match Mongoose model expectations and required fields.
 * Overwrites the original files with normalized content safe for seeding.
 *
 * Usage:
 *   node scripts/normalize-seeddata.js
 */

const fs = require("fs");
const path = require("path");

const OUT = path.join(__dirname, "..", "seedData");
if (!fs.existsSync(OUT)) {
  console.error("seedData directory not found at", OUT);
  process.exit(1);
}

function read(name) {
  const p = path.join(OUT, name);
  if (!fs.existsSync(p)) return [];
  try {
    return JSON.parse(fs.readFileSync(p, "utf8")) || [];
  } catch (e) {
    console.warn("Failed to parse", p, e.message);
    return [];
  }
}

function slug(s) {
  return (s || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

// Map freeform industry strings into allowed enum values from Company model
function normalizeIndustry(raw) {
  if (!raw) return "Other";
  const r = raw.toLowerCase();
  if (r.includes("manufact")) return "Manufacturing";
  if (r.includes("nurs") || r.includes("care")) return "Nursing Care";
  if (r.includes("construct")) return "Construction";
  if (r.includes("agric") || r.includes("farming")) return "Agriculture";
  if (r.includes("food") && r.includes("service")) return "Food Service";
  if (r.includes("hospital") || r.includes("hotel")) return "Hospitality";
  if (r.includes("processing")) return "Food Processing";
  if (r.includes("machin") || r.includes("industrial"))
    return "Industrial Machinery";
  if (r.includes("elect") || r.includes("electronics"))
    return "Electric & Electronics";
  if (r.includes("clean")) return "Building Cleaning";
  if (r.includes("ship")) return "Shipbuilding";
  if (r.includes("auto") || r.includes("repair")) return "Auto Repair";
  if (r.includes("aviat")) return "Aviation";
  if (r.includes("accommodation")) return "Accommodation";
  // fallback: try to match a single known token
  const known = [
    "Manufacturing",
    "Nursing Care",
    "Construction",
    "Agriculture",
    "Food Service",
    "Hospitality",
    "Food Processing",
    "Industrial Machinery",
    "Electric & Electronics",
    "Building Cleaning",
    "Shipbuilding",
    "Auto Repair",
    "Aviation",
    "Accommodation",
    "Other",
  ];
  for (const k of known) if (r.includes(k.toLowerCase())) return k;
  return "Other";
}

function ensureUrl(u) {
  if (!u) return null;
  if (/^https?:\/\//i.test(u)) return u;
  return "https://" + u.replace(/^\//, "");
}

function normalizeCompanies(companiesRaw) {
  const out = companiesRaw.map((c, i) => {
    const name = c.name || c.title || `Company ${i + 1}`;
    const normalizedIndustry = normalizeIndustry(
      c.industry || c.description || "",
    );
    const companySlug = slug(name) || `company-${i + 1}`;
    return {
      name,
      slug: companySlug,
      industry: normalizedIndustry,
      size: c.size || "51-200",
      founded: c.founded || 2018,
      website: ensureUrl(c.website) || `https://${companySlug}.example`,
      description: c.description || `Profile for ${name}`,
      location: {
        prefecture:
          (c.location && c.location.prefecture) || c.location || "Tokyo",
        city:
          (c.location && c.location.city) ||
          (c.location && c.location.city) ||
          "Shinjuku",
      },
      contact: {
        email: (c.contact && c.contact.email) || `hr@${companySlug}.example`,
        phone: (c.contact && c.contact.phone) || "+81-3-0000-0000",
      },
      ownerEmail: c.ownerEmail || "employer+seed@example.com",
      // keep source for traceability
      _source: c.source || null,
    };
  });
  return out;
}

function normalizeJobs(jobsRaw, companiesNormalized) {
  const companiesByName = {};
  for (const comp of companiesNormalized) companiesByName[comp.name] = comp;

  return jobsRaw.map((j, i) => {
    const title = j.title || `Job ${i + 1}`;
    const companyName =
      j.companyName ||
      j.company ||
      (j.companyName && j.companyName) ||
      (j.company && j.company) ||
      (companiesNormalized[0] && companiesNormalized[0].name) ||
      "Seed Company Ltd";
    const company = companiesByName[companyName] ||
      companiesNormalized[0] || { name: companyName };
    const normalizedIndustry = normalizeIndustry(
      j.industry || company.industry || "Other",
    );
    const jobSlug = slug(`${company.name}-${title}`);
    return {
      title,
      companyName: company.name,
      industry: normalizedIndustry,
      category:
        j.category || /engineer|engineering/i.test(title)
          ? "Engineering"
          : j.category || "General",
      summary:
        j.summary ||
        (j.description ? j.description.split("\n")[0] : null) ||
        null,
      description: j.description || j.summary || null,
      postedByEmail: j.postedByEmail || "employer+seed@example.com",
      location: j.location ||
        company.location || { prefecture: "Tokyo", city: "Shibuya" },
      compensation: j.compensation || {
        salaryMin: 200000,
        salaryMax: 350000,
        currency: "JPY",
        period: "monthly",
      },
      applicationInfo: j.applicationInfo || {
        deadline: new Date(Date.now() + 60 * 24 * 60 * 60 * 1000).toISOString(),
        applicationMethod: "Platform",
      },
      status: j.status || "active",
      _source: j.source || null,
    };
  });
}

function normalizeProfiles(profilesRaw) {
  return profilesRaw.map((p, i) => {
    const display =
      p.displayName || p.title || p.name || `seed-profile-${i + 1}`;
    const names = (p.displayName || p.title || "").split(" ");
    const firstName = p.firstName || (names.length ? names[0] : "Seed");
    const lastName =
      p.lastName || (names.length > 1 ? names.slice(1).join(" ") : "Jobseeker");
    return {
      userEmail: p.userEmail || `jobseeker+seed@example.com`,
      firstName,
      lastName,
      dateOfBirth: p.dateOfBirth || "1995-01-01",
      nationality: p.nationality || "Japan",
      phone: p.phone || null,
      city: (p.location && p.location.city) || p.city || "Tokyo",
      prefecture:
        (p.location && p.location.prefecture) || p.prefecture || "Tokyo",
      languages:
        p.languages && p.languages.length
          ? p.languages.map((l) => ({
              language: l.language || l.name || "Japanese",
              level: l.level || l.level || "conversational",
            }))
          : [{ language: "Japanese", level: "conversational" }],
      availability: p.availability || {
        visaStatus: "not-applicable",
        relocate: false,
      },
      summary: p.summary || null,
      _source: p.source || null,
    };
  });
}

function write(name, data) {
  const p = path.join(OUT, name);
  fs.writeFileSync(p, JSON.stringify(data, null, 2));
  console.log("Wrote", p, `(${data.length} items)`);
}

function main() {
  console.log("Normalizing seedData in", OUT);
  const companiesRaw = read("companies.json");
  const jobsRaw = read("jobs.json");
  const profilesRaw = read("profiles.json");

  const companies = normalizeCompanies(companiesRaw);
  const jobs = normalizeJobs(jobsRaw, companies);
  const profiles = normalizeProfiles(profilesRaw);

  // Overwrite originals so seedDatabase.js / fixSeedData.js can consume directly
  write("companies.json", companies);
  write("jobs.json", jobs);
  write("profiles.json", profiles);

  console.log(
    "Normalization complete. Review files in seedData/ before seeding.",
  );
}

main();
